function PublishButton({ draftId }: { draftId: string }) {
  const [busy, setBusy] = useState(false);

  const onClick = async () => {
    setBusy(true);
    const res = await fetch(`/api/publish/${draftId}`, { method: 'POST' });
    if (!res.ok) {
      throw new Error(`publish failed: ${res.status}`);
    }
    setBusy(false);
    toast('Published');
  };

  useEffect(() => {
    const id = setInterval(() => {
      refreshStatus(draftId); // returns a promise, not awaited
    }, 5000);
    return () => clearInterval(id);
  }, [draftId]);

  return <button disabled={busy} onClick={onClick}>Publish</button>;
}
